use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};

use futures_util::stream::StreamExt;
use netlink_packet_core::{
    NetlinkMessage, NLM_F_ACK, NLM_F_CREATE, NLM_F_EXCL, NLM_F_REPLACE,
    NLM_F_REQUEST,
};
use netlink_packet_route::{address::AddressMessage, RouteNetlinkMessage};

use crate::{addr::AddressMessageBuilder, try_nl, Error, Handle};

/// A request to create a new address. This is equivalent to the `ip address
/// add` commands.
pub struct AddressAddRequest {
    handle: Handle,
    message: AddressMessage,
    replace: bool,
}

impl AddressAddRequest {
    pub(crate) fn new(
        handle: Handle,
        index: u32,
        address: IpAddr,
        prefix_len: u8,
    ) -> Self {
        let message = match address {
            IpAddr::V4(address) => AddressMessageBuilder::<Ipv4Addr>::new()
                .index(index)
                .address(address, prefix_len)
                .build(),
            IpAddr::V6(address) => AddressMessageBuilder::<Ipv6Addr>::new()
                .index(index)
                .address(address, prefix_len)
                .build(),
        };

        AddressAddRequest {
            handle,
            message,
            replace: false,
        }
    }

    /// Replace existing matching address.
    pub fn replace(self) -> Self {
        Self {
            replace: true,
            ..self
        }
    }

    /// Execute the request.
    pub async fn execute(self) -> Result<(), Error> {
        let AddressAddRequest {
            mut handle,
            message,
            replace,
        } = self;
        let mut req =
            NetlinkMessage::from(RouteNetlinkMessage::NewAddress(message));
        let replace = if replace { NLM_F_REPLACE } else { NLM_F_EXCL };
        req.header.flags = NLM_F_REQUEST | NLM_F_ACK | replace | NLM_F_CREATE;

        let mut response = handle.request(req)?;
        while let Some(message) = response.next().await {
            try_nl!(message);
        }
        Ok(())
    }

    /// Return a mutable reference to the request message.
    pub fn message_mut(&mut self) -> &mut AddressMessage {
        &mut self.message
    }
}// SPDX-License-Identifier: MIT

use std::{
    marker::PhantomData,
    net::{Ipv4Addr, Ipv6Addr},
};

use netlink_packet_route::{
    address::{AddressAttribute, AddressMessage},
    AddressFamily,
};

#[derive(Debug)]
/// Helper struct for building [AddressMessage].
pub struct AddressMessageBuilder<T> {
    message: AddressMessage,
    _phantom: PhantomData<T>,
}

impl<T> AddressMessageBuilder<T> {
    /// Create a new [AddressMessageBuilder] without specifying the address
    /// family.
    fn new_no_address_family() -> Self {
        AddressMessageBuilder {
            message: AddressMessage::default(),
            _phantom: PhantomData,
        }
    }

    /// Sets the interface index.
    pub fn index(mut self, index: u32) -> Self {
        self.message.header.index = index;
        self
    }

    /// Builds [AddressMessage].
    pub fn build(self) -> AddressMessage {
        self.message
    }
}

impl Default for AddressMessageBuilder<Ipv4Addr> {
    fn default() -> Self {
        Self::new()
    }
}

impl AddressMessageBuilder<Ipv4Addr> {
    /// Create a new [AddressMessageBuilder] for IPv4 addresses.
    pub fn new() -> Self {
        let mut builder = Self::new_no_address_family();
        builder.message.header.family = AddressFamily::Inet;
        builder
    }

    /// Sets the address and prefix length.
    pub fn address(mut self, address: Ipv4Addr, prefix_len: u8) -> Self {
        self.message.header.prefix_len = prefix_len;

        if !address.is_multicast() {
            self.message
                .attributes
                .push(AddressAttribute::Address(address.into()));

            // The IFA_LOCAL address can be set to the same value as
            // IFA_ADDRESS.
            self.message
                .attributes
                .push(AddressAttribute::Local(address.into()));

            // Set the IFA_BROADCAST address as well.
            if prefix_len < 31 {
                let ip_addr = u32::from(address);
                let brd = Ipv4Addr::from(
                    (0xffff_ffff_u32) >> u32::from(prefix_len) | ip_addr,
                );
                self.message
                    .attributes
                    .push(AddressAttribute::Broadcast(brd));
            };
        }

        self
    }
}

impl Default for AddressMessageBuilder<Ipv6Addr> {
    fn default() -> Self {
        Self::new()
    }
}

impl AddressMessageBuilder<Ipv6Addr> {
    /// Create a new [AddressMessageBuilder] for IPv6 addresses.
    pub fn new() -> Self {
        let mut builder = Self::new_no_address_family();
        builder.message.header.family = AddressFamily::Inet6;
        builder
    }

    /// Sets the address and prefix length.
    pub fn address(mut self, address: Ipv6Addr, prefix_len: u8) -> Self {
        self.message.header.prefix_len = prefix_len;

        if address.is_multicast() {
            self.message
                .attributes
                .push(AddressAttribute::Multicast(address));
        } else {
            self.message
                .attributes
                .push(AddressAttribute::Address(address.into()));

            // The IFA_LOCAL address can be set to the same value as
            // IFA_ADDRESS.
            self.message
                .attributes
                .push(AddressAttribute::Local(address.into()));
        }

        self
    }
}// SPDX-License-Identifier: MIT

use futures_util::stream::StreamExt;
use netlink_packet_core::{NetlinkMessage, NLM_F_ACK, NLM_F_REQUEST};
use netlink_packet_route::{address::AddressMessage, RouteNetlinkMessage};

use crate::{try_nl, Error, Handle};

pub struct AddressDelRequest {
    handle: Handle,
    message: AddressMessage,
}

impl AddressDelRequest {
    pub(crate) fn new(handle: Handle, message: AddressMessage) -> Self {
        AddressDelRequest { handle, message }
    }

    /// Execute the request
    pub async fn execute(self) -> Result<(), Error> {
        let AddressDelRequest {
            mut handle,
            message,
        } = self;

        let mut req =
            NetlinkMessage::from(RouteNetlinkMessage::DelAddress(message));
        req.header.flags = NLM_F_REQUEST | NLM_F_ACK;
        let mut response = handle.request(req)?;
        while let Some(msg) = response.next().await {
            try_nl!(msg);
        }
        Ok(())
    }

    pub fn message_mut(&mut self) -> &mut AddressMessage {
        &mut self.message
    }
}// SPDX-License-Identifier: MIT

use std::net::IpAddr;

use futures_util::{
    future::{self, Either},
    stream::{Stream, StreamExt, TryStreamExt},
    FutureExt,
};
use netlink_packet_core::{NetlinkMessage, NLM_F_DUMP, NLM_F_REQUEST};
use netlink_packet_route::{
    address::{AddressAttribute, AddressMessage},
    RouteNetlinkMessage,
};

use crate::{try_rtnl, Error, Handle};

pub struct AddressGetRequest {
    handle: Handle,
    message: AddressMessage,
    filter_builder: AddressFilterBuilder,
}

impl AddressGetRequest {
    pub(crate) fn new(handle: Handle) -> Self {
        AddressGetRequest {
            handle,
            message: AddressMessage::default(),
            filter_builder: AddressFilterBuilder::new(),
        }
    }

    pub fn message_mut(&mut self) -> &mut AddressMessage {
        &mut self.message
    }

    pub fn execute(self) -> impl Stream<Item = Result<AddressMessage, Error>> {
        let AddressGetRequest {
            mut handle,
            message,
            filter_builder,
        } = self;

        let mut req =
            NetlinkMessage::from(RouteNetlinkMessage::GetAddress(message));
        req.header.flags = NLM_F_REQUEST | NLM_F_DUMP;

        let filter = filter_builder.build();
        match handle.request(req) {
            Ok(response) => Either::Left(
                response
                    .map(move |msg| {
                        Ok(try_rtnl!(msg, RouteNetlinkMessage::NewAddress))
                    })
                    .try_filter(move |msg| future::ready(filter(msg))),
            ),
            Err(e) => Either::Right(
                future::err::<AddressMessage, Error>(e).into_stream(),
            ),
        }
    }

    /// Return only the addresses of the given interface.
    pub fn set_link_index_filter(mut self, index: u32) -> Self {
        self.filter_builder.index = Some(index);
        self
    }

    /// Return only the addresses of the given prefix length.
    pub fn set_prefix_length_filter(mut self, prefix: u8) -> Self {
        self.filter_builder.prefix_len = Some(prefix);
        self
    }

    /// Return only AddressMessages filtered by the given address.
    pub fn set_address_filter(mut self, address: IpAddr) -> Self {
        self.filter_builder.address = Some(address);
        self
    }
}

// The reason for having filters, is that we cannot retrieve addresses
// that match the given message, like we do for links.
//
// See:
// https://lists.infradead.org/pipermail/libnl/2013-June/001014.html
// https://patchwork.ozlabs.org/patch/133440/
#[derive(Default)]
struct AddressFilterBuilder {
    index: Option<u32>,
    address: Option<IpAddr>,
    prefix_len: Option<u8>,
}

impl AddressFilterBuilder {
    fn new() -> Self {
        Default::default()
    }

    fn build(self) -> impl Fn(&AddressMessage) -> bool {
        use AddressAttribute::*;

        move |msg: &AddressMessage| {
            if let Some(index) = self.index {
                if msg.header.index != index {
                    return false;
                }
            }

            if let Some(prefix_len) = self.prefix_len {
                if msg.header.prefix_len != prefix_len {
                    return false;
                }
            }

            if let Some(address) = self.address {
                for nla in msg.attributes.iter() {
                    if let Address(x) | Local(x) = nla {
                        if x == &address {
                            return true;
                        }
                    } else if let Multicast(x) | Anycast(x) = nla {
                        if IpAddr::V6(*x) == address {
                            return true;
                        }
                    }
                }
                return false;
            }
            true
        }
    }
}// SPDX-License-Identifier: MIT

use std::net::IpAddr;

use netlink_packet_route::address::AddressMessage;

use super::{AddressAddRequest, AddressDelRequest, AddressGetRequest};
use crate::Handle;

pub struct AddressHandle(Handle);

impl AddressHandle {
    pub fn new(handle: Handle) -> Self {
        AddressHandle(handle)
    }

    /// Retrieve the list of ip addresses (equivalent to `ip addr show`)
    pub fn get(&self) -> AddressGetRequest {
        AddressGetRequest::new(self.0.clone())
    }

    /// Add an ip address on an interface (equivalent to `ip addr add`)
    pub fn add(
        &self,
        index: u32,
        address: IpAddr,
        prefix_len: u8,
    ) -> AddressAddRequest {
        AddressAddRequest::new(self.0.clone(), index, address, prefix_len)
    }

    /// Delete the given address
    pub fn del(&self, address: AddressMessage) -> AddressDelRequest {
        AddressDelRequest::new(self.0.clone(), address)
    }
}// SPDX-License-Identifier: MIT

