    /// Append arbitrary [InfoBridgePort]
    pub fn append_info_data(self, info: InfoBridgePort) -> Self {
        let mut ret = self;

        if let InfoPortData::BridgePort(infos) = ret
            .port_data
            .get_or_insert_with(|| InfoPortData::BridgePort(Vec::new()))
        {
            infos.push(info);
        }

        ret
    }

