use crate::{
    packet_route::link::{InfoData, InfoKind, InfoVxlan},
    LinkMessageBuilder,
};

/// Represent VxLAN interface.
/// Example code on creating a VxLAN interface
/// ```no_run
/// use rtnetlink::{new_connection, LinkVxlan};
/// #[tokio::main]
/// async fn main() -> Result<(), String> {
///     let (connection, handle, _) = new_connection().unwrap();
///     tokio::spawn(connection);
///
///     handle
///         .link()
///         .add(LinkVxlan::new("vxlan100", 100)
///         .dev(10)
///         .port(4789)
///         .up()
///         .build())
///         .execute()
///         .await
///         .map_err(|e| format!("{e}"))
/// }
/// ```
///
/// Please check LinkMessageBuilder::<LinkVlan> for more detail.
#[derive(Default, Debug)]
pub struct LinkVxlan;

impl LinkVxlan {
    /// Wrapper of `LinkMessageBuilder::<LinkVxlan>::new().id()`
    pub fn new(name: &str, vni: u32) -> LinkMessageBuilder<Self> {
        LinkMessageBuilder::<LinkVxlan>::new(name).id(vni)
    }
}

impl LinkMessageBuilder<LinkVxlan> {
    /// Create [LinkMessageBuilder] for VLAN
    pub fn new(name: &str) -> Self {
        LinkMessageBuilder::<LinkVxlan>::new_with_info_kind(InfoKind::Vxlan)
            .name(name.to_string())
    }

    pub fn append_info_data(self, info: InfoVxlan) -> Self {
        let mut ret = self;
        if let InfoData::Vxlan(infos) = ret
            .info_data
            .get_or_insert_with(|| InfoData::Vxlan(Vec::new()))
        {
            infos.push(info);
        }
        ret
    }

    /// VNI
    pub fn id(self, id: u32) -> Self {
        self.append_info_data(InfoVxlan::Id(id))
    }

    /// This is equivalent to `devPHYS_DEV` for ip link vxlan.
    /// Adds the `dev` attribute to the VXLAN
    /// This is equivalent to `ip link add name NAME type vxlan id VNI dev
    /// LINK`,  dev LINK - specifies the physical device to use
    ///  for tunnel endpoint communication.
    /// But instead of specifing a link name (`LINK`), we specify a link index.
    /// Please be aware the `LinkMessageBuilder::link()` will not works for
    /// VxLAN.
    pub fn dev(self, index: u32) -> Self {
        self.append_info_data(InfoVxlan::Link(index))
    }

    /// Adds the `dstport` attribute to the VXLAN
    /// This is equivalent to `ip link add name NAME type vxlan id VNI dstport
    /// PORT`. dstport PORT - specifies the UDP destination port to
    /// communicate to the remote VXLAN tunnel endpoint.
    pub fn port(self, port: u16) -> Self {
        self.append_info_data(InfoVxlan::Port(port))
    }

    /// Adds the `group` attribute to the VXLAN
    /// This is equivalent to `ip link add name NAME type vxlan id VNI group
    /// IPADDR`, group IPADDR - specifies the multicast IP address to join.
    /// This function takes an IPv4 address
    /// WARNING: only one between `remote` and `group` can be present.
    pub fn group(self, addr: std::net::Ipv4Addr) -> Self {
        self.append_info_data(InfoVxlan::Group(addr))
    }

    /// Adds the `group` attribute to the VXLAN
    /// This is equivalent to `ip link add name NAME type vxlan id VNI group
    /// IPADDR`, group IPADDR - specifies the multicast IP address to join.
    /// This function takes an IPv6 address
    /// WARNING: only one between `remote` and `group` can be present.
    pub fn group6(self, addr: std::net::Ipv6Addr) -> Self {
        self.append_info_data(InfoVxlan::Group6(addr))
    }

    /// Adds the `remote` attribute to the VXLAN
    /// This is equivalent to `ip link add name NAME type vxlan id VNI remote
    /// IPADDR`, remote IPADDR - specifies the unicast destination IP
    /// address to use in outgoing packets when the
    /// destination link layer address is not known in the
    /// VXLAN device forwarding database.
    /// This function takes an IPv4 address.
    /// WARNING: only one between `remote` and `group` can be present.
    pub fn remote(self, addr: std::net::Ipv4Addr) -> Self {
        self.group(addr)
    }

    /// Adds the `remote` attribute to the VXLAN
    /// This is equivalent to `ip link add name NAME type vxlan id VNI remote
    /// IPADDR`, remote IPADDR - specifies the unicast destination IP
    /// address to use in outgoing packets when the
    /// destination link layer address is not known in the
    /// VXLAN device forwarding database.
    /// This function takes an IPv6 address.
    /// WARNING: only one between `remote` and `group` can be present.
    pub fn remote6(self, addr: std::net::Ipv6Addr) -> Self {
        self.group6(addr)
    }

    /// Adds the `local` attribute to the VXLAN
    /// This is equivalent to `ip link add name NAME type vxlan id VNI local
    /// IPADDR`, local IPADDR - specifies the source IP address to use in
    /// outgoing packets. This function takes an IPv4 address.
    pub fn local(self, addr: std::net::Ipv4Addr) -> Self {
        self.append_info_data(InfoVxlan::Local(addr))
    }

    /// Adds the `local` attribute to the VXLAN
    /// This is equivalent to `ip link add name NAME type vxlan id VNI local
    /// IPADDR`, local IPADDR - specifies the source IP address to use in
    /// outgoing packets. This function takes an IPv6 address.
    pub fn local6(self, addr: std::net::Ipv6Addr) -> Self {
        self.append_info_data(InfoVxlan::Local6(addr))
    }

    /// Adds the `tos` attribute to the VXLAN
    /// This is equivalent to `ip link add name NAME type vxlan id VNI tos TOS`.
    /// tos TOS - specifies the TOS value to use in outgoing packets.
    pub fn tos(self, tos: u8) -> Self {
        self.append_info_data(InfoVxlan::Tos(tos))
    }

    /// Adds the `ttl` attribute to the VXLAN
    /// This is equivalent to `ip link add name NAME type vxlan id VNI ttl TTL`.
    /// ttl TTL - specifies the TTL value to use in outgoing packets.
    pub fn ttl(self, ttl: u8) -> Self {
        self.append_info_data(InfoVxlan::Ttl(ttl))
    }

    /// Adds the `flowlabel` attribute to the VXLAN
    /// This is equivalent to `ip link add name NAME type vxlan id VNI flowlabel
    /// LABEL`. flowlabel LABEL - specifies the flow label to use in
    /// outgoing packets.
    pub fn label(self, label: u32) -> Self {
        self.append_info_data(InfoVxlan::Label(label))
    }

    /// Adds the `learning` attribute to the VXLAN
    /// This is equivalent to `ip link add name NAME type vxlan id VNI
    /// \[no\]learning`. \[no\]learning - specifies if unknown source link layer
    /// addresses and IP addresses are entered into the VXLAN
    /// device forwarding database.
    pub fn learning(self, learning: bool) -> Self {
        self.append_info_data(InfoVxlan::Learning(learning))
    }

    /// Adds the `ageing` attribute to the VXLAN
    /// This is equivalent to `ip link add name NAME type vxlan id VNI ageing
    /// SECONDS`. ageing SECONDS - specifies the lifetime in seconds of
    /// FDB entries learnt by the kernel.
    pub fn ageing(self, seconds: u32) -> Self {
        self.append_info_data(InfoVxlan::Ageing(seconds))
    }

    /// Adds the `maxaddress` attribute to the VXLAN
    /// This is equivalent to `ip link add name NAME type vxlan id VNI
    /// maxaddress LIMIT`. maxaddress LIMIT - specifies the maximum number
    /// of FDB entries.
    pub fn limit(self, limit: u32) -> Self {
        self.append_info_data(InfoVxlan::Limit(limit))
    }

    /// Adds the `srcport` attribute to the VXLAN
    /// This is equivalent to `ip link add name NAME type vxlan id VNI srcport
    /// MIN MAX`. srcport MIN MAX - specifies the range of port numbers
    /// to use as UDP source ports to communicate to the
    /// remote VXLAN tunnel endpoint.
    pub fn port_range(self, min: u16, max: u16) -> Self {
        self.append_info_data(InfoVxlan::PortRange((min, max)))
    }

    /// Adds the `proxy` attribute to the VXLAN
    /// This is equivalent to `ip link add name NAME type vxlan id VNI
    /// [no]proxy`. \[no\]proxy - specifies ARP proxy is turned on.
    pub fn proxy(self, proxy: bool) -> Self {
        self.append_info_data(InfoVxlan::Proxy(proxy))
    }

    /// Adds the `rsc` attribute to the VXLAN This is equivalent to
    /// `ip link add name NAME type vxlan id VNI [no]rsc`.
    /// \[no\]rsc - specifies if route short circuit is turned on.
    pub fn rsc(self, rsc: bool) -> Self {
        self.append_info_data(InfoVxlan::Rsc(rsc))
    }

    // Adds the `l2miss` attribute to the VXLAN
    /// This is equivalent to `ip link add name NAME type vxlan id VNI
    /// [no]l2miss`. \[no\]l2miss - specifies if netlink LLADDR miss
    /// notifications are generated.
    pub fn l2miss(self, l2miss: bool) -> Self {
        self.append_info_data(InfoVxlan::L2Miss(l2miss))
    }

    // Adds the `l3miss` attribute to the VXLAN
    /// This is equivalent to `ip link add name NAME type vxlan id VNI
    /// [no]l3miss`. \[no\]l3miss - specifies if netlink IP ADDR
    /// miss notifications are generated.
    pub fn l3miss(self, l3miss: bool) -> Self {
        self.append_info_data(InfoVxlan::L3Miss(l3miss))
    }

    pub fn collect_metadata(self, collect_metadata: bool) -> Self {
        self.append_info_data(InfoVxlan::CollectMetadata(collect_metadata))
    }

    // Adds the `localbypass` attribute to the VXLAN
    /// This is equivalent to `ip link add name NAME type vxlan id VNI
    /// [no]localbypass`. \[no\]localbypass - specifies if the VXLAN
    /// localbypass mode is turned on.
    pub fn localbypass(self, localbypass: bool) -> Self {
        self.append_info_data(InfoVxlan::Localbypass(localbypass))
    }

    // Adds the `udp_csum` attribute to the VXLAN
    /// This is equivalent to `ip link add name NAME type vxlan id VNI
    /// [no]udp_csum`. \[no\]udpcsum - specifies if UDP checksum is
    /// calculated for transmitted packets over IPv4.
    pub fn udp_csum(self, udp_csum: bool) -> Self {
        self.append_info_data(InfoVxlan::UDPCsum(udp_csum))
    }

    /// Sets the IPv6 flow label policy.
    ///
    /// Kernel enum: `VXLAN_LABEL_FIXED = 0`, `VXLAN_LABEL_INHERIT = 1`.
    /// This is equivalent to `ip link add name NAME type vxlan id VNI
    /// label_policy POLICY`.
    pub fn label_policy(self, policy: u32) -> Self {
        self.append_info_data(InfoVxlan::LabelPolicy(policy))
    }

    /// Tolerated reserved bits in VxLAN header.
    ///
    /// When set to 1 on certain reserved bit, linux kernel will not
    /// reject(drop and count as error) the VxLAN packet with that reserved
    /// bits set to 1.
    /// This is equivalent to `ip link add name NAME type vxlan id VNI
    /// reserved_bits VALUE`.
    pub fn reserved_bits(self, bits: u64) -> Self {
        self.append_info_data(InfoVxlan::ReservedBits(bits))
    }

    /// Adds the `mc_route` attribute to the VXLAN
    /// This is equivalent to `ip link add name NAME type vxlan id VNI
    /// [no]mc_route`. \[no\]mc_route - specifies if multicast routing
    /// is enabled.
    pub fn mc_route(self, mc_route: bool) -> Self {
        self.append_info_data(InfoVxlan::McRoute(mc_route))
    }
}// SPDX-License-Identifier: MIT

use crate::{link::LinkMessageBuilder, packet_route::link::InfoKind};

/// Represent wireguard interface.
/// Example code on creating a wireguard interface
/// ```no_run
/// use rtnetlink::{new_connection, LinkWireguard};
/// #[tokio::main]
/// async fn main() -> Result<(), String> {
///     let (connection, handle, _) = new_connection().unwrap();
///     tokio::spawn(connection);
///
///     handle
///         .link()
///         .add(LinkWireguard::new("wg0").build())
///         .execute()
///         .await
///         .map_err(|e| format!("{e}"))
/// }
/// ```
///
/// Please check LinkMessageBuilder::<LinkWireguard> for more detail.
#[derive(Default, Debug)]
pub struct LinkWireguard;

impl LinkWireguard {
    /// Equal to `LinkMessageBuilder::<LinkWireguard>::new()`
    pub fn new(name: &str) -> LinkMessageBuilder<Self> {
        LinkMessageBuilder::<LinkWireguard>::new(name)
    }
}

impl LinkMessageBuilder<LinkWireguard> {
    /// Create [LinkMessageBuilder] for wireguard
    pub fn new(name: &str) -> Self {
        LinkMessageBuilder::<LinkWireguard>::new_with_info_kind(
            InfoKind::Wireguard,
        )
        .name(name.to_string())
    }
}// SPDX-License-Identifier: MIT

use crate::{
    link::LinkMessageBuilder,
    packet_route::link::{InfoData, InfoKind, InfoXfrm},
};

/// Represent XFRM interface.
/// Example code on creating a XFRM interface
/// ```no_run
/// use rtnetlink::{new_connection, LinkXfrm};
/// #[tokio::main]
/// async fn main() -> Result<(), String> {
///     let (connection, handle, _) = new_connection().unwrap();
///     tokio::spawn(connection);
///
///     handle
///         .link()
///         .add(LinkXfrm::new("xfrm8", 9, 0x08).build())
///         .execute()
///         .await
///         .map_err(|e| format!("{e}"))
/// }
/// ```
///
/// Please check LinkMessageBuilder::<LinkXfrm> for more detail.
#[derive(Default, Debug)]
pub struct LinkXfrm;

impl LinkXfrm {
    /// Equal to `LinkMessageBuilder::<LinkXfrm>::new().dev().if_id()`
    pub fn new(
        name: &str,
        base_iface_index: u32,
        if_id: u32,
    ) -> LinkMessageBuilder<Self> {
        LinkMessageBuilder::<LinkXfrm>::new(name)
            .dev(base_iface_index)
            .if_id(if_id)
    }
}

impl LinkMessageBuilder<LinkXfrm> {
    /// Create [LinkMessageBuilder] for XFRM
    pub fn new(name: &str) -> Self {
        LinkMessageBuilder::<LinkXfrm>::new_with_info_kind(InfoKind::Xfrm)
            .name(name.to_string())
    }

    pub fn append_info_data(mut self, info: InfoXfrm) -> Self {
        if let InfoData::Xfrm(infos) = self
            .info_data
            .get_or_insert_with(|| InfoData::Xfrm(Vec::new()))
        {
            infos.push(info);
        }
        self
    }

    /// This is equivalent to the `if_id IF_ID` in command
    /// `ip link add name NAME type xfrm if_id IF_ID`.
    pub fn if_id(self, if_id: u32) -> Self {
        self.append_info_data(InfoXfrm::IfId(if_id))
    }

    /// This is equivalent to the `dev PHYS_DEV` in command
    /// `ip link add name NAME type xfm dev PHYS_DEV`, only take the interface
    /// index.
    pub fn dev(self, iface_index: u32) -> Self {
        self.append_info_data(InfoXfrm::Link(iface_index))
    }
}// SPDX-License-Identifier: MIT

use std::net::IpAddr;

use futures_util::stream::StreamExt;
use netlink_packet_core::{
    NetlinkMessage, NetlinkPayload, NLM_F_ACK, NLM_F_CREATE, NLM_F_EXCL,
    NLM_F_REPLACE, NLM_F_REQUEST,
};
use netlink_packet_route::{
    neighbour::{
        NeighbourAddress, NeighbourAttribute, NeighbourFlags, NeighbourMessage,
        NeighbourState,
    },
    route::RouteType,
    AddressFamily, RouteNetlinkMessage,
};

use crate::{Error, Handle};

pub struct NeighbourAddRequest {
    handle: Handle,
    message: NeighbourMessage,
    replace: bool,
}

impl NeighbourAddRequest {
    pub(crate) fn new(handle: Handle, index: u32, destination: IpAddr) -> Self {
        let mut message = NeighbourMessage::default();

        message.header.family = match destination {
            IpAddr::V4(_) => AddressFamily::Inet,
            IpAddr::V6(_) => AddressFamily::Inet6,
        };

        message.header.ifindex = index;
        message.header.state = NeighbourState::Permanent;
        message.header.kind = RouteType::Unspec;

        message.attributes.push(NeighbourAttribute::Destination(
            match destination {
                IpAddr::V4(v4) => NeighbourAddress::Inet(v4),
                IpAddr::V6(v6) => NeighbourAddress::Inet6(v6),
            },
        ));

        NeighbourAddRequest {
            handle,
            message,
            replace: false,
        }
    }

    #[cfg(not(target_os = "freebsd"))]
    pub(crate) fn new_bridge(handle: Handle, index: u32, lla: &[u8]) -> Self {
        let mut message = NeighbourMessage::default();

        message.header.family = AddressFamily::Bridge;
        message.header.ifindex = index;
        message.header.state = NeighbourState::Permanent;
        message.header.kind = RouteType::Unspec;

        message
            .attributes
            .push(NeighbourAttribute::LinkLayerAddress(lla.to_vec()));

        NeighbourAddRequest {
            handle,
            message,
            replace: false,
        }
    }

    /// Set a bitmask of states for the neighbor cache entry.
    /// It should be a combination of `NUD_*` constants.
    pub fn state(mut self, state: NeighbourState) -> Self {
        self.message.header.state = state;
        self
    }

    /// Set flags for the neighbor cache entry.
    /// It should be a combination of `NTF_*` constants.
    pub fn flags(mut self, flags: NeighbourFlags) -> Self {
        self.message.header.flags = flags;
        self
    }

    /// Set attributes applicable to the the neighbor cache entry.
    /// It should be one of `NDA_*` constants.
    pub fn kind(mut self, kind: RouteType) -> Self {
        self.message.header.kind = kind;
        self
    }

    #[deprecated(
        since = "0.21.0",
        note = "please use `link_layer_address` instead"
    )]
    /// Set a neighbor cache link layer address (see `NDA_LLADDR` for details).
    /// Deprecated. Please use [NeighbourAddRequest::link_layer_address()]
    /// instead.
    pub fn link_local_address(self, addr: &[u8]) -> Self {
        self.link_layer_address(addr)
    }

    /// Set a neighbor cache link layer address (see `NDA_LLADDR` for details).
    pub fn link_layer_address(mut self, addr: &[u8]) -> Self {
        let lla =
            self.message
                .attributes
                .iter_mut()
                .find_map(|nla| match nla {
                    NeighbourAttribute::LinkLayerAddress(lla) => Some(lla),
                    _ => None,
                });

        if let Some(lla) = lla {
            *lla = addr.to_vec();
        } else {
            self.message
                .attributes
                .push(NeighbourAttribute::LinkLayerAddress(addr.to_vec()));
        }

        self
    }

    /// Set the destination address for the neighbour (see `NDA_DST` for
    /// details).
    pub fn destination(mut self, addr: IpAddr) -> Self {
        let dst =
            self.message
                .attributes
                .iter_mut()
                .find_map(|nla| match nla {
                    NeighbourAttribute::Destination(dst) => Some(dst),
                    _ => None,
                });

        let addr = match addr {
            IpAddr::V4(v4) => NeighbourAddress::Inet(v4),
            IpAddr::V6(v6) => NeighbourAddress::Inet6(v6),
        };

        if let Some(dst) = dst {
            *dst = addr;
        } else {
            self.message
                .attributes
                .push(NeighbourAttribute::Destination(addr));
        }

        self
    }

    /// Replace existing matching neighbor.
    pub fn replace(self) -> Self {
        Self {
            replace: true,
            ..self
        }
    }

    /// Execute the request.
    pub async fn execute(self) -> Result<(), Error> {
        let NeighbourAddRequest {
            mut handle,
            message,
            replace,
        } = self;

        let mut req =
            NetlinkMessage::from(RouteNetlinkMessage::NewNeighbour(message));
        let replace = if replace { NLM_F_REPLACE } else { NLM_F_EXCL };
        req.header.flags = NLM_F_REQUEST | NLM_F_ACK | replace | NLM_F_CREATE;

        let mut response = handle.request(req)?;
        while let Some(message) = response.next().await {
            if let NetlinkPayload::Error(err) = message.payload {
                return Err(Error::NetlinkError(err));
            }
        }

        Ok(())
    }

    /// Return a mutable reference to the request message.
    pub fn message_mut(&mut self) -> &mut NeighbourMessage {
        &mut self.message
    }
}// SPDX-License-Identifier: MIT

use futures_util::stream::StreamExt;
use netlink_packet_core::{
    NetlinkMessage, NetlinkPayload, NLM_F_ACK, NLM_F_REQUEST,
};
use netlink_packet_route::{neighbour::NeighbourMessage, RouteNetlinkMessage};

use crate::{Error, Handle};

pub struct NeighbourDelRequest {
    handle: Handle,
    message: NeighbourMessage,
}

impl NeighbourDelRequest {
    pub(crate) fn new(handle: Handle, message: NeighbourMessage) -> Self {
        NeighbourDelRequest { handle, message }
    }

    /// Execute the request
    pub async fn execute(self) -> Result<(), Error> {
        let NeighbourDelRequest {
            mut handle,
            message,
        } = self;

        let mut req =
            NetlinkMessage::from(RouteNetlinkMessage::DelNeighbour(message));
        req.header.flags = NLM_F_REQUEST | NLM_F_ACK;
        let mut response = handle.request(req)?;
        while let Some(msg) = response.next().await {
            if let NetlinkPayload::Error(e) = msg.payload {
                return Err(Error::NetlinkError(e));
            }
        }
        Ok(())
    }

    pub fn message_mut(&mut self) -> &mut NeighbourMessage {
        &mut self.message
    }
}// SPDX-License-Identifier: MIT

use futures_util::{
    future::{self, Either},
    stream::{Stream, StreamExt},
    FutureExt,
};
use netlink_packet_core::{
    NetlinkMessage, NetlinkPayload, NLM_F_DUMP, NLM_F_REQUEST,
};
use netlink_packet_route::{
    neighbour::{NeighbourFlags, NeighbourMessage},
    AddressFamily, RouteNetlinkMessage,
};

use crate::{Error, Handle, IpVersion};

pub struct NeighbourGetRequest {
    handle: Handle,
    message: NeighbourMessage,
}

impl NeighbourGetRequest {
    pub(crate) fn new(handle: Handle) -> Self {
        let message = NeighbourMessage::default();
        NeighbourGetRequest { handle, message }
    }

    /// List neighbor proxies in the system (equivalent to: `ip neighbor show
    /// proxy`).
    pub fn proxies(mut self) -> Self {
        self.message.header.flags |= NeighbourFlags::Proxy;
        self
    }

    #[deprecated(
        since = "0.22.0",
        note = "please use `set_address_family` instead"
    )]
    pub fn set_family(mut self, ip_version: IpVersion) -> Self {
        self.message.header.family = ip_version.family();
        self
    }

    pub fn set_address_family(mut self, family: AddressFamily) -> Self {
        self.message.header.family = family;
        self
    }

    pub fn set_flags(mut self, flags: NeighbourFlags) -> Self {
        self.message.header.flags = flags;
        self
    }

    /// Execute the request
    pub fn execute(
        self,
    ) -> impl Stream<Item = Result<NeighbourMessage, Error>> {
        let NeighbourGetRequest {
            mut handle,
            message,
        } = self;

        let mut req =
            NetlinkMessage::from(RouteNetlinkMessage::GetNeighbour(message));
        req.header.flags = NLM_F_REQUEST | NLM_F_DUMP;

        match handle.request(req) {
            Ok(response) => Either::Left(response.map(move |msg| {
                let (header, payload) = msg.into_parts();
                match payload {
                    NetlinkPayload::InnerMessage(
                        RouteNetlinkMessage::NewNeighbour(msg),
                    ) => Ok(msg),
                    NetlinkPayload::Error(err) => Err(Error::NetlinkError(err)),
                    _ => Err(Error::UnexpectedMessage(NetlinkMessage::new(
                        header, payload,
                    ))),
                }
            })),
            Err(e) => Either::Right(
                future::err::<NeighbourMessage, Error>(e).into_stream(),
            ),
        }
    }

    /// Return a mutable reference to the request
    pub fn message_mut(&mut self) -> &mut NeighbourMessage {
        &mut self.message
    }
}// SPDX-License-Identifier: MIT

use std::net::IpAddr;

use netlink_packet_route::neighbour::NeighbourMessage;

use crate::{
    Handle, NeighbourAddRequest, NeighbourDelRequest, NeighbourGetRequest,
};

pub struct NeighbourHandle(Handle);

impl NeighbourHandle {
    pub fn new(handle: Handle) -> Self {
        NeighbourHandle(handle)
    }

    /// List neighbour entries (equivalent to `ip neighbour show`)
    pub fn get(&self) -> NeighbourGetRequest {
        NeighbourGetRequest::new(self.0.clone())
    }

    /// Add a new neighbour entry (equivalent to `ip neighbour add`)
    pub fn add(&self, index: u32, destination: IpAddr) -> NeighbourAddRequest {
        NeighbourAddRequest::new(self.0.clone(), index, destination)
    }

    #[cfg(not(target_os = "freebsd"))]
    /// Add a new fdb entry (equivalent to `bridge fdb add`)
    pub fn add_bridge(&self, index: u32, lla: &[u8]) -> NeighbourAddRequest {
        NeighbourAddRequest::new_bridge(self.0.clone(), index, lla)
    }

    /// Delete a neighbour entry (equivalent to `ip neighbour delete`)
    pub fn del(&self, message: NeighbourMessage) -> NeighbourDelRequest {
        NeighbourDelRequest::new(self.0.clone(), message)
    }
}// SPDX-License-Identifier: MIT

